.brain-fab-pulse{
  position:absolute;
  inset:-8px;
  border-radius:inherit;
  border:1px solid rgba(97,246,255,.32);
  animation:fabPulse 2.4s ease-in-out infinite;
}

.brain-fab-text{
  position:relative;
}

.brain-window{
  border:1px solid rgba(255,255,255,.18);
  border-radius:24px;
  background:rgba(5,3,11,.92);
  backdrop-filter:blur(18px);
  box-shadow:0 28px 100px rgba(0,0,0,.55),0 0 46px rgba(97,246,255,.12);
  overflow:hidden;
  transform-origin:bottom right;
  animation:chatRise .45s ease both;
}

.brain-head{
  min-height:70px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:14px 16px;
  border-bottom:1px solid rgba(255,255,255,.12);
  background:linear-gradient(90deg,rgba(255,215,106,.12),rgba(97,246,255,.08),rgba(255,79,216,.09));
}

.brain-head div{
  display:grid;
  grid-template-columns:auto auto;
  column-gap:8px;
  align-items:center;
}

.brain-head small{
  grid-column:2;
  color:var(--muted);
  font-size:.78rem;
}

.brain-status{
  width:10px;
  height:10px;
  border-radius:50%;
  background:var(--cyan);
  box-shadow:0 0 18px var(--cyan);
}

.brain-head button{
  width:38px;
  height:38px;
  border-radius:14px;
  border:1px solid rgba(255,255,255,.16);
  background:rgba(255,255,255,.06);
  color:var(--text);
  cursor:pointer;
  font-weight:950;
}

.brain-messages{
  height:300px;
  overflow:auto;
  padding:16px;
  display:flex;
  flex-direction:column;
  gap:10px;
  scrollbar-width:thin;
}

.brain-message{
  max-width:86%;
  border-radius:18px;
  padding:11px 13px;
  color:var(--text);
  line-height:1.42;
  font-size:.94rem;
}

.from-brain{
  align-self:flex-start;
  background:rgba(97,246,255,.09);
  border:1px solid rgba(97,246,255,.18);
}

.from-user{
  align-self:flex-end;
  background:rgba(255,215,106,.13);
  border:1px solid rgba(255,215,106,.22);
}

.brain-form{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  gap:8px;
  padding:12px;
  border-top:1px solid rgba(255,255,255,.12);
}

.brain-form input{
  border-radius:16px;
  min-height:48px;
}

.brain-form button{
  border:1px solid rgba(255,215,106,.46);
  border-radius:16px;
  background:rgba(255,215,106,.18);
  color:var(--text);
  font-weight:900;
  padding:0 14px;
  cursor:pointer;
}

.brain-widget.is-minimized .brain-window{
  display:none;
}

.brain-widget.is-minimized .brain-fab{
  display:grid;
  place-items:center;
}

::-webkit-scrollbar{
  width:14px;
  height:14px;
}

::-webkit-scrollbar-track{
  background:rgba(255,255,255,.08);
}

::-webkit-scrollbar-thumb{
  background:linear-gradient(180deg,var(--gold),var(--cyan),var(--pink));
  border:3px solid rgba(5,3,11,.90);
  border-radius:999px;
}

@keyframes gridDrift{
  from{background-position:0 0,0 0}
  to{background-position:0 78px,78px 0}
}

@keyframes orbitPulse{
  0%,100%{transform:scale(.88);opacity:.20}
  50%{transform:scale(1.14);opacity:.64}
}

@keyframes logoFloat{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-12px)}
}

@keyframes titleShimmer{
  from{background-position:0% center}
  to{background-position:220% center}
}

@keyframes orbitTilt{
  0%,100%{transform:rotateX(0deg) rotateY(0deg)}
  50%{transform:rotateX(7deg) rotateY(-8deg)}
}

@keyframes spinOrbit{
  to{transform:rotate(360deg)}
}

@keyframes nodeFloat{
  0%,100%{margin-top:0}
  50%{margin-top:-12px}
}

@keyframes lineFlash{
  0%,100%{opacity:.15}
  50%{opacity:.55}
}

@keyframes sweep{
  0%,62%{translate:-120% 0}
  100%{translate:120% 0}
}

@keyframes consoleScan{
