    width:100%;
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:8px;
  }
  .nav-links a{
    white-space:normal;
    text-align:center;
    padding:10px 9px;
  }
  .nav-links .button{
    grid-column:1/-1;
  }
  .hero{
    padding-top:34px;
  }
  .hero-logo{
    width:min(420px,96%);
  }
  .card,.card.large{
    grid-column:1/-1;
  }
  .legal-doc{
    border-radius:24px;
    padding:20px;
  }
  .toc{
    padding:18px;
  }
  .toc a{
    font-size:.9rem;
  }
  h1{
    letter-spacing:-.045em;
  }
}

@media(max-width:430px){
  .nav-links{
    grid-template-columns:1fr;
  }
  .brand-logo{
    width:52px;
  }
  .hero-logo{
    width:min(360px,98%);
  }
}


/* =========================================================
   HARD FIX: legal page overlap correction
   Root cause: global .card { grid-column: span 4; } was affecting
   .legal-layout children. Legal layout must own its children directly.
   ========================================================= */

.legal-layout{
  display:grid !important;
  grid-template-columns:minmax(240px,300px) minmax(0,1fr) !important;
  gap:28px !important;
  align-items:start !important;
  width:100% !important;
}

.legal-layout > .toc,
.legal-layout > .card.toc{
  grid-column:1 !important;
  grid-row:1 !important;
  width:100% !important;
  min-width:0 !important;
  max-width:300px !important;
  align-self:start !important;
}

.legal-layout > .legal-doc{
  grid-column:2 !important;
  grid-row:1 !important;
  width:100% !important;
  min-width:0 !important;
  max-width:100% !important;
  align-self:start !important;
}

.legal-layout .card{
  grid-column:auto !important;
}

.legal-layout .legal-doc h2{
  word-break:normal !important;
  overflow-wrap:break-word !important;
  hyphens:none !important;
}

.legal-layout .legal-doc p,
.legal-layout .legal-doc li{
  overflow-wrap:break-word !important;
}

@media(max-width:1120px){
  .legal-layout{
    grid-template-columns:1fr !important;
    gap:18px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc,
  .legal-layout > .legal-doc{
    grid-column:1 !important;
    grid-row:auto !important;
    max-width:none !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    position:relative !important;
    top:auto !important;
    max-height:none !important;
    overflow:visible !important;
  }
}

@media(max-width:760px){
  .legal-layout{
    gap:14px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    padding:16px !important;
  }

  .legal-layout > .legal-doc{
    padding:20px !important;
  }
}


