:root{
  --bg:#05030b;
  --bg2:#13091f;
  --panel:rgba(255,255,255,.078);
  --panel2:rgba(255,255,255,.12);
  --text:#fff8e7;
  --muted:#d9cbea;
  --gold:#ffd76a;
  --purple:#9b5cff;
  --pink:#ff4fd8;
  --cyan:#61f6ff;
  --line:rgba(255,255,255,.16);
  --line2:rgba(255,215,106,.32);
  --shadow:0 24px 80px rgba(0,0,0,.48);
  --radius:28px;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}

*{box-sizing:border-box}

html{
  min-height:100%;
  scroll-behavior:smooth;
  scroll-padding-top:24px;
  background:
    radial-gradient(circle at 10% 12%,rgba(255,215,106,.23),transparent 29%),
    radial-gradient(circle at 90% 4%,rgba(155,92,255,.32),transparent 35%),
    radial-gradient(circle at 48% 95%,rgba(97,246,255,.12),transparent 40%),
    linear-gradient(180deg,var(--bg),var(--bg2));
}

body{
  margin:0;
  color:var(--text);
  line-height:1.62;
  overflow-x:hidden;
  min-width:320px;
}

body:before{
  content:"";
  position:fixed;
  inset:0;
  pointer-events:none;
  background:
    linear-gradient(rgba(255,255,255,.026) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.026) 1px,transparent 1px);
  background-size:42px 42px;
  mask-image:linear-gradient(to bottom,rgba(0,0,0,.8),transparent 76%);
  z-index:-2;
}

body:after{
  content:"";
  position:fixed;
  width:420px;
  height:420px;
  border-radius:50%;
  pointer-events:none;
  left:var(--cursor-x,50%);
  top:var(--cursor-y,38%);
  translate:-50% -50%;
  background:radial-gradient(circle,rgba(255,215,106,.16),rgba(155,92,255,.11),transparent 70%);
  filter:blur(8px);
  z-index:-1;
}

a{color:var(--gold);text-decoration:none}
a:hover{color:var(--cyan)}

.wrap{width:min(1180px,calc(100% - 36px));margin:0 auto}
.narrow{width:min(940px,calc(100% - 36px));margin:0 auto}

.site-header{
  position:relative;
  z-index:20;
  background:linear-gradient(180deg,rgba(6,4,13,.96),rgba(6,4,13,.82));
  border-bottom:1px solid var(--line);
  box-shadow:0 18px 60px rgba(0,0,0,.28);
}

.nav{
  min-height:94px;
  display:grid;
  grid-template-columns:minmax(260px,auto) minmax(0,1fr);
  align-items:center;
  gap:22px;
  padding:12px 0;
}

.brand{
  display:inline-flex;
  align-items:center;
  gap:12px;
  font-weight:950;
  letter-spacing:.04em;
  text-transform:uppercase;
  color:var(--text);
  min-width:0;
}

.brand-logo{
  width:76px;
  height:auto;
  display:block;
  object-fit:contain;
  flex:0 0 auto;
  filter:drop-shadow(0 0 18px rgba(255,215,106,.34));
}

.brand span:last-child{
  min-width:0;
  overflow-wrap:anywhere;
}

.brand-skye{color:var(--gold)}
.brand-london{
  background:linear-gradient(90deg,var(--gold),var(--purple),var(--pink));
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
}

.nav-links{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  flex-wrap:wrap;
  min-width:0;
}

.nav-links a{
  color:var(--muted);
  font-size:.93rem;
  border:1px solid rgba(255,255,255,.10);
  background:rgba(255,255,255,.045);
  border-radius:999px;
  padding:9px 12px;
  line-height:1.1;
  white-space:nowrap;
}

.nav-links a[aria-current=page],.nav-links a:hover{
  color:var(--text);
  border-color:rgba(255,215,106,.40);
  background:rgba(255,215,106,.08);
}

.nav-links .button,
.button{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:44px;
  padding:0 18px;
  border-radius:999px;
  border:1px solid rgba(255,215,106,.45);
  background:linear-gradient(135deg,rgba(255,215,106,.24),rgba(155,92,255,.2));
  color:var(--text);
  font-weight:850;
  box-shadow:0 12px 44px rgba(155,92,255,.16);
  cursor:pointer;
}

.button:hover{
  color:var(--text);
  border-color:rgba(97,246,255,.65);
}

.hero{padding:54px 0 32px}
.hero.center{text-align:center}

.hero-logo{
  display:block;
  width:min(560px,92%);
  height:auto;
  margin:0 auto 22px;
  filter:drop-shadow(0 0 36px rgba(255,215,106,.30)) drop-shadow(0 0 52px rgba(155,92,255,.23));
}

.eyebrow{
  color:var(--cyan);
  letter-spacing:.16em;
  text-transform:uppercase;
  font-size:.78rem;
  font-weight:850;
  margin-bottom:16px;
}

h1{
  font-size:clamp(2.1rem,5.7vw,5rem);
  line-height:.98;
  margin:0 0 20px;
  letter-spacing:0;
}

.page-title{font-size:clamp(2rem,4.6vw,4.1rem)}

h2{
  font-size:clamp(1.48rem,2.8vw,2.45rem);
  line-height:1.1;
  margin:0 0 16px;
  letter-spacing:0;
}

h3{font-size:1.15rem;margin:20px 0 6px}

.lede{
  max-width:900px;
  color:var(--muted);
  font-size:clamp(1.05rem,1.65vw,1.28rem);
  margin:0 0 24px;
}

.center .lede{margin-left:auto;margin-right:auto}

.glow-title{text-shadow:0 0 38px rgba(255,215,106,.24),0 0 48px rgba(155,92,255,.22)}

.grid{
  display:grid;
  grid-template-columns:repeat(12,minmax(0,1fr));
  gap:18px;
  margin:26px 0;
}

.card{
  grid-column:span 4;
  background:linear-gradient(180deg,var(--panel),rgba(255,255,255,.035));
  border:1px solid var(--line);
  border-radius:var(--radius);
  padding:24px;
  box-shadow:var(--shadow);
  position:relative;
  overflow:hidden;
  min-width:0;
}

.card.large{grid-column:span 8}
.card.full{grid-column:1/-1}

.card:before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(135deg,rgba(255,215,106,.08),transparent 35%,rgba(155,92,255,.09));
}

.card>*{position:relative}

.section{padding:34px 0}

.kicker{
  color:var(--gold);
  font-weight:850;
  text-transform:uppercase;
  letter-spacing:.12em;
  font-size:.78rem;
}

.copy p,.copy li{color:var(--muted)}
.copy strong{color:var(--text)}
.copy h2,.copy h3{color:var(--text)}

.list{
  padding-left:1.15rem;
  margin:12px 0 0;
}

.notice{
  border:1px solid rgba(255,215,106,.42);
  background:rgba(255,215,106,.08);
  color:var(--text);
  border-radius:22px;
  padding:18px;
}

.carrier-copy-section{
  border:1px solid rgba(255,215,106,.46);
  background:linear-gradient(135deg,rgba(255,215,106,.13),rgba(97,246,255,.07));
}

.carrier-copy-section p{
  color:var(--text);
  font-size:1.05rem;
}

.danger{
  border-color:rgba(255,79,216,.48);
  background:rgba(255,79,216,.075);
}

.badge-row{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  margin-top:18px;
}

.center .badge-row{justify-content:center}

.badge{
  border:1px solid var(--line);
  border-radius:999px;
  padding:8px 12px;
  color:var(--muted);
  background:rgba(255,255,255,.045);
  font-size:.88rem;
}

.legal-layout{
  display:grid;
  grid-template-columns:minmax(230px,280px) minmax(0,1fr);
  gap:24px;
  align-items:start;
}

.toc{
  position:sticky;
  top:22px;
  max-height:calc(100vh - 44px);
  overflow:auto;
  z-index:1;
}

.toc a{
  display:block;
  padding:9px 0;
  color:var(--muted);
  border-bottom:1px solid rgba(255,255,255,.07);
  font-size:.94rem;
  overflow-wrap:anywhere;
}

.toc a:hover{color:var(--gold)}

.legal-doc{
  background:linear-gradient(180deg,var(--panel),rgba(255,255,255,.035));
  border:1px solid var(--line);
  border-radius:30px;
  padding:clamp(22px,4vw,42px);
  box-shadow:var(--shadow);
  min-width:0;
  overflow-wrap:anywhere;
}

.legal-doc p,.legal-doc li{color:var(--muted)}

.legal-doc section{
  padding:22px 0;
  border-top:1px solid rgba(255,255,255,.10);
  scroll-margin-top:24px;
}

.legal-doc section:first-of-type{
  border-top:0;
  padding-top:0;
}

.meta{color:var(--muted);font-size:.95rem}

.table-wrap{
  width:100%;
  overflow-x:auto;
  border-radius:18px;
}

.table{
  width:100%;
  border-collapse:collapse;
  min-width:680px;
}

.table th,.table td{
  padding:14px;
  border-bottom:1px solid var(--line);
  text-align:left;
  vertical-align:top;
}

.table th{
  color:var(--gold);
  background:rgba(255,255,255,.055);
}

.table td{color:var(--muted)}

.form{display:grid;gap:14px}

label{
  display:grid;
  gap:8px;
  color:var(--text);
  font-weight:750;
}

input,textarea,select{
  width:100%;
  border:1px solid rgba(255,255,255,.18);
  background:rgba(0,0,0,.28);
  border-radius:16px;
  color:var(--text);
  padding:14px;
  font:inherit;
  outline:none;
}

textarea{min-height:138px;resize:vertical}

input:focus,textarea:focus,select:focus{
  border-color:var(--gold);
  box-shadow:0 0 0 4px rgba(255,215,106,.12);
}

.checkbox{
  display:grid;
  grid-template-columns:22px minmax(0,1fr);
  gap:12px;
  align-items:start;
  color:var(--muted);
  font-weight:500;
}

.checkbox input{
  width:18px;
  height:18px;
  margin-top:4px;
}

.required{color:var(--gold);font-weight:900}
.small{font-size:.92rem;color:var(--muted)}

.footer{
  margin-top:50px;
  border-top:1px solid var(--line);
  padding:30px 0 44px;
  color:var(--muted);
  background:rgba(0,0,0,.12);
}

.footer-grid{
  display:flex;
  justify-content:space-between;
  gap:22px;
  flex-wrap:wrap;
}

.footer-logo{
  width:108px;
  height:auto;
  display:block;
  margin-bottom:10px;
  filter:drop-shadow(0 0 16px rgba(255,215,106,.2));
}

@media(max-width:1120px){
  .nav{
    grid-template-columns:1fr;
    align-items:start;
  }
  .nav-links{
    justify-content:flex-start;
  }
  .legal-layout{
    grid-template-columns:1fr;
  }
  .toc{
    position:relative;
    top:auto;
    max-height:none;
  }
  .toc a{
    display:inline-flex;
    margin:4px 6px 4px 0;
    padding:8px 11px;
    border:1px solid rgba(255,255,255,.10);
    border-radius:999px;
    background:rgba(255,255,255,.045);
  }
}

@media(max-width:760px){
  .wrap,.narrow{
    width:min(100% - 26px,1180px);
  }
  .site-header{
    position:relative;
  }
  .nav{
    min-height:auto;
    gap:14px;
    padding:14px 0 16px;
  }
  .brand{
    align-items:flex-start;
    font-size:.92rem;
    line-height:1.15;
  }
  .brand-logo{
    width:58px;
  }
  .nav-links{
    width:100%;
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:8px;
  }
  .nav-links a{
    white-space:normal;
    text-align:center;
    padding:10px 9px;
  }
  .nav-links .button{
    grid-column:1/-1;
  }
  .hero{
    padding-top:34px;
  }
  .hero-logo{
    width:min(420px,96%);
  }
  .card,.card.large{
    grid-column:1/-1;
  }
  .legal-doc{
    border-radius:24px;
    padding:20px;
  }
  .toc{
    padding:18px;
  }
  .toc a{
    font-size:.9rem;
  }
  h1{
    letter-spacing:-.045em;
  }
}

@media(max-width:430px){
  .nav-links{
    grid-template-columns:1fr;
  }
  .brand-logo{
    width:52px;
  }
  .hero-logo{
    width:min(360px,98%);
  }
}


/* =========================================================
   HARD FIX: legal page overlap correction
   Root cause: global .card { grid-column: span 4; } was affecting
   .legal-layout children. Legal layout must own its children directly.
   ========================================================= */

.legal-layout{
  display:grid !important;
  grid-template-columns:minmax(240px,300px) minmax(0,1fr) !important;
  gap:28px !important;
  align-items:start !important;
  width:100% !important;
}

.legal-layout > .toc,
.legal-layout > .card.toc{
  grid-column:1 !important;
  grid-row:1 !important;
  width:100% !important;
  min-width:0 !important;
  max-width:300px !important;
  align-self:start !important;
}

.legal-layout > .legal-doc{
  grid-column:2 !important;
  grid-row:1 !important;
  width:100% !important;
  min-width:0 !important;
  max-width:100% !important;
  align-self:start !important;
}

.legal-layout .card{
  grid-column:auto !important;
}

.legal-layout .legal-doc h2{
  word-break:normal !important;
  overflow-wrap:break-word !important;
  hyphens:none !important;
}

.legal-layout .legal-doc p,
.legal-layout .legal-doc li{
  overflow-wrap:break-word !important;
}

@media(max-width:1120px){
  .legal-layout{
    grid-template-columns:1fr !important;
    gap:18px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc,
  .legal-layout > .legal-doc{
    grid-column:1 !important;
    grid-row:auto !important;
    max-width:none !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    position:relative !important;
    top:auto !important;
    max-height:none !important;
    overflow:visible !important;
  }
}

@media(max-width:760px){
  .legal-layout{
    gap:14px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    padding:16px !important;
  }

  .legal-layout > .legal-doc{
    padding:20px !important;
  }
}


/* =========================================================
   FULLSCREEN WIDTH PASS
   The legal pages now use the full browser width with small gutters.
   ========================================================= */

.wrap{
  width:calc(100vw - 28px) !important;
  max-width:none !important;
  margin-left:auto !important;
  margin-right:auto !important;
}

.narrow{
  width:calc(100vw - 28px) !important;
  max-width:1500px !important;
  margin-left:auto !important;
  margin-right:auto !important;
}

.site-header .wrap{
  width:calc(100vw - 28px) !important;
  max-width:none !important;
}

.legal-layout{
  width:100% !important;
  max-width:none !important;
  grid-template-columns:minmax(270px,340px) minmax(0,1fr) !important;
}

.legal-layout > .toc,
.legal-layout > .card.toc{
  max-width:340px !important;
}

.legal-layout > .legal-doc{
  width:100% !important;
  max-width:none !important;
}

.legal-doc{
  width:100% !important;
  max-width:none !important;
}

.grid{
  width:100% !important;
  max-width:none !important;
}

.hero-logo{
  width:min(620px,92vw) !important;
}

@media(min-width:1600px){
  .legal-layout{
    grid-template-columns:minmax(300px,380px) minmax(0,1fr) !important;
    gap:32px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    max-width:380px !important;
  }

  .legal-doc{
    padding:48px !important;
  }
}

@media(max-width:1120px){
  .wrap,
  .narrow,
  .site-header .wrap{
    width:calc(100vw - 24px) !important;
  }

  .legal-layout{
    grid-template-columns:1fr !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    max-width:none !important;
  }
}

@media(max-width:760px){
  .wrap,
  .narrow,
  .site-header .wrap{
    width:calc(100vw - 20px) !important;
  }
}

/* Legal Skyes command homepage */

.sr-only{
  position:absolute;
  width:1px;
  height:1px;
  padding:0;
  margin:-1px;
  overflow:hidden;
  clip:rect(0,0,0,0);
  white-space:nowrap;
  border:0;
}

.home-shell{
  background:
    radial-gradient(circle at 20% 14%,rgba(255,215,106,.20),transparent 30%),
    radial-gradient(circle at 82% 18%,rgba(97,246,255,.15),transparent 32%),
    radial-gradient(circle at 50% 90%,rgba(255,79,216,.11),transparent 38%),
    linear-gradient(180deg,#030208 0%,#0d0618 46%,#05030b 100%);
}

.legal-command-hero{
  position:relative;
  min-height:calc(100vh - 94px);
  overflow:hidden;
  display:grid;
  align-items:center;
  padding:46px 0 70px;
  isolation:isolate;
}

.command-bg{
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index:-1;
}

.grid-scan{
  position:absolute;
  inset:-20%;
  background:
    linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px),
    linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px);
  background-size:78px 78px;
  transform:perspective(900px) rotateX(64deg) translateY(8%);
  transform-origin:bottom center;
  animation:gridDrift 12s linear infinite;
  opacity:.38;
  mask-image:linear-gradient(to bottom,transparent 0%,#000 20%,#000 72%,transparent 100%);
}

.pulse-ring{
  position:absolute;
  width:48vmin;
  height:48vmin;
  border:1px solid rgba(255,215,106,.30);
  border-radius:50%;
  filter:drop-shadow(0 0 22px rgba(255,215,106,.18));
  animation:orbitPulse 5.6s ease-in-out infinite;
}

.ring-one{right:9%;top:16%}
.ring-two{right:19%;top:30%;animation-delay:-1.5s;border-color:rgba(97,246,255,.28)}
.ring-three{left:4%;bottom:4%;animation-delay:-3s;border-color:rgba(255,79,216,.24)}

.command-layout{
  display:grid;
  grid-template-columns:minmax(0,1.02fr) minmax(380px,.78fr);
  gap:clamp(28px,5vw,70px);
  align-items:center;
}

.command-logo{
  width:min(300px,48vw);
  height:auto;
  display:block;
  margin-bottom:20px;
  filter:drop-shadow(0 0 42px rgba(255,215,106,.34)) drop-shadow(0 0 56px rgba(97,246,255,.16));
  animation:logoFloat 5.8s ease-in-out infinite;
}

.spectacle-title{
  max-width:980px;
  font-size:clamp(3rem,7.4vw,7.8rem);
  line-height:.92;
  margin-bottom:24px;
  text-wrap:balance;
  background:linear-gradient(92deg,#fff8e7 0%,#ffd76a 30%,#61f6ff 60%,#ff4fd8 86%,#fff8e7 100%);
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
  background-size:220% auto;
  animation:titleShimmer 7s linear infinite;
  text-shadow:none;
}

.command-copy .lede{
  max-width:820px;
}

.command-actions{
  display:flex;
  gap:12px;
  flex-wrap:wrap;
  margin:26px 0;
}

.ghost-button{
  background:rgba(255,255,255,.055);
  border-color:rgba(97,246,255,.45);
}

.signal-strip{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  max-width:920px;
}

.signal-strip span{
  min-height:72px;
  border:1px solid rgba(255,255,255,.14);
  background:linear-gradient(180deg,rgba(255,255,255,.095),rgba(255,255,255,.035));
  border-radius:18px;
  padding:13px;
  color:var(--muted);
  display:grid;
  align-content:center;
  box-shadow:0 16px 54px rgba(0,0,0,.24);
}

.signal-strip strong{
  color:var(--gold);
  font-size:1.25rem;
  line-height:1;
}

.legal-orbit{
  position:relative;
  aspect-ratio:1;
  min-height:460px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:
    radial-gradient(circle,rgba(255,215,106,.22),transparent 16%),
    radial-gradient(circle,rgba(97,246,255,.12),transparent 34%),
    radial-gradient(circle,transparent 47%,rgba(255,255,255,.08) 48%,transparent 49%),
    radial-gradient(circle,transparent 66%,rgba(255,215,106,.18) 67%,transparent 68%);
  animation:orbitTilt 9s ease-in-out infinite;
}

.legal-orbit:before,
.legal-orbit:after{
  content:"";
  position:absolute;
  inset:8%;
  border:1px solid rgba(255,255,255,.15);
  border-radius:50%;
  animation:spinOrbit 18s linear infinite;
}

.legal-orbit:after{
  inset:21%;
  border-color:rgba(97,246,255,.18);
  animation-duration:11s;
  animation-direction:reverse;
}

.orbit-core{
  position:relative;
  z-index:2;
  width:min(250px,52%);
  aspect-ratio:1;
  border-radius:50%;
  border:1px solid rgba(255,215,106,.46);
  background:radial-gradient(circle at 30% 20%,rgba(255,255,255,.22),rgba(255,215,106,.14) 36%,rgba(5,3,11,.90) 72%);
  display:grid;
  place-items:center;
  align-content:center;
  text-align:center;
  padding:24px;
  box-shadow:0 0 74px rgba(255,215,106,.22),inset 0 0 44px rgba(255,255,255,.05);
}

.orbit-core strong{
  font-size:clamp(1.35rem,2.4vw,2rem);
  line-height:1.05;
}

.orbit-core small,
.core-kicker{
  color:var(--muted);
}

.core-kicker{
  color:var(--cyan);
  font-size:.74rem;
  letter-spacing:.14em;
  text-transform:uppercase;
  font-weight:900;
}

.policy-node{
  position:absolute;
  z-index:3;
  width:94px;
  aspect-ratio:1;
  border-radius:50%;
  border:1px solid rgba(255,255,255,.18);
  background:linear-gradient(145deg,rgba(255,255,255,.16),rgba(255,255,255,.045));
  display:grid;
  place-items:center;
  color:var(--text);
  font-weight:900;
  box-shadow:0 18px 44px rgba(0,0,0,.34),0 0 28px rgba(97,246,255,.13);
  animation:nodeFloat 4s ease-in-out infinite;
}

.policy-node:hover{
  color:var(--text);
  border-color:rgba(255,215,106,.75);
  transform:scale(1.06);
}

.node-terms{top:3%;left:50%;translate:-50% 0}
.node-privacy{top:26%;right:1%;animation-delay:-.7s}
.node-ai{right:12%;bottom:11%;animation-delay:-1.3s}
.node-sms{left:12%;bottom:11%;animation-delay:-2.1s}
.node-saas{top:26%;left:1%;animation-delay:-2.8s}
.node-dmca{bottom:0;left:50%;translate:-50% 0;animation-delay:-3.4s}

.orbit-line{
  position:absolute;
  inset:14%;
  border-top:1px solid rgba(255,215,106,.20);
  transform:rotate(var(--angle));
  animation:lineFlash 4.8s ease-in-out infinite;
}

.orbit-line-a{--angle:24deg}
.orbit-line-b{--angle:94deg;animation-delay:-1.6s}
.orbit-line-c{--angle:154deg;animation-delay:-3.2s}

.section-intro{
  max-width:860px;
  margin-bottom:24px;
}

.section-intro p{
  color:var(--muted);
}

.route-board{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:14px;
}

.route-tile{
  min-height:260px;
  border:1px solid rgba(255,255,255,.14);
  border-radius:24px;
  padding:20px;
  background:linear-gradient(180deg,rgba(255,255,255,.09),rgba(255,255,255,.035));
  color:var(--text);
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  overflow:hidden;
  position:relative;
  box-shadow:0 22px 70px rgba(0,0,0,.28);
}

.route-tile:before{
  content:"";
  position:absolute;
  inset:-80% -20%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.18),transparent);
  transform:rotate(18deg);
  animation:sweep 7s ease-in-out infinite;
}

.route-tile>*{
  position:relative;
}

.route-tile.hot{
  border-color:rgba(255,215,106,.42);
}

.route-index{
  color:var(--cyan);
  font-weight:950;
}

.route-tile strong{
  font-size:1.34rem;
  line-height:1.1;
}

.route-tile span:last-child{
  color:var(--muted);
}

.brain-demo-grid{
  display:grid;
  grid-template-columns:minmax(0,.82fr) minmax(360px,1fr);
  gap:20px;
  align-items:stretch;
}

.brain-panel,
.brain-console{
  border:1px solid rgba(255,255,255,.14);
  border-radius:26px;
  background:linear-gradient(180deg,rgba(255,255,255,.10),rgba(255,255,255,.04));
  padding:24px;
  box-shadow:var(--shadow);
}

.brain-panel p{
  color:var(--muted);
}

.brain-prompts{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin-top:18px;
}

.brain-prompts button{
  border:1px solid rgba(97,246,255,.28);
  border-radius:999px;
  background:rgba(97,246,255,.08);
  color:var(--text);
  padding:10px 12px;
  cursor:pointer;
  font:inherit;
}

.brain-prompts button:hover{
  border-color:rgba(255,215,106,.62);
}

.brain-console{
  background:#05030b;
  overflow:hidden;
  position:relative;
}

.brain-console:before{
  content:"";
  position:absolute;
  inset:0;
  background:repeating-linear-gradient(180deg,rgba(97,246,255,.045) 0 1px,transparent 1px 7px);
  pointer-events:none;
  animation:consoleScan 2.8s linear infinite;
}

.console-bar,
.console-lines{
  position:relative;
}

.console-bar{
  display:flex;
  gap:8px;
  align-items:center;
  border-bottom:1px solid rgba(255,255,255,.12);
  padding-bottom:14px;
  margin-bottom:18px;
}

.console-bar span{
  width:12px;
  height:12px;
  border-radius:50%;
  background:var(--pink);
}

.console-bar span:nth-child(2){background:var(--gold)}
.console-bar span:nth-child(3){background:var(--cyan)}
.console-bar strong{margin-left:auto;color:var(--muted);font-size:.86rem}
.console-lines p{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text)}
.console-lines span{color:var(--cyan)}

.brain-widget{
  position:fixed;
  right:20px;
  bottom:20px;
  z-index:80;
  width:min(390px,calc(100vw - 28px));
  pointer-events:none;
}

.brain-fab,
.brain-window{
  pointer-events:auto;
}

.brain-fab{
  position:absolute;
  right:0;
  bottom:0;
  width:74px;
  height:74px;
  border-radius:50%;
  border:1px solid rgba(255,215,106,.62);
  color:var(--text);
  background:radial-gradient(circle at 35% 20%,rgba(255,255,255,.25),rgba(255,215,106,.25) 32%,rgba(155,92,255,.42) 72%);
  box-shadow:0 16px 48px rgba(0,0,0,.42),0 0 36px rgba(255,215,106,.24);
  font-weight:950;
  cursor:pointer;
  display:none;
}

.brain-fab-pulse{
  position:absolute;
  inset:-8px;
  border-radius:inherit;
  border:1px solid rgba(97,246,255,.32);
  animation:fabPulse 2.4s ease-in-out infinite;
}

.brain-fab-text{
  position:relative;
}

.brain-window{
  border:1px solid rgba(255,255,255,.18);
  border-radius:24px;
  background:rgba(5,3,11,.92);
  backdrop-filter:blur(18px);
  box-shadow:0 28px 100px rgba(0,0,0,.55),0 0 46px rgba(97,246,255,.12);
  overflow:hidden;
  transform-origin:bottom right;
  animation:chatRise .45s ease both;
}

.brain-head{
  min-height:70px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:14px 16px;
  border-bottom:1px solid rgba(255,255,255,.12);
  background:linear-gradient(90deg,rgba(255,215,106,.12),rgba(97,246,255,.08),rgba(255,79,216,.09));
}

.brain-head div{
  display:grid;
  grid-template-columns:auto auto;
  column-gap:8px;
  align-items:center;
}

.brain-head small{
  grid-column:2;
  color:var(--muted);
  font-size:.78rem;
}

.brain-status{
  width:10px;
  height:10px;
  border-radius:50%;
  background:var(--cyan);
  box-shadow:0 0 18px var(--cyan);
}

.brain-head button{
  width:38px;
  height:38px;
  border-radius:14px;
  border:1px solid rgba(255,255,255,.16);
  background:rgba(255,255,255,.06);
  color:var(--text);
  cursor:pointer;
  font-weight:950;
}

.brain-messages{
  height:300px;
  overflow:auto;
  padding:16px;
  display:flex;
  flex-direction:column;
  gap:10px;
  scrollbar-width:thin;
}

.brain-message{
  max-width:86%;
  border-radius:18px;
  padding:11px 13px;
  color:var(--text);
  line-height:1.42;
  font-size:.94rem;
}

.from-brain{
  align-self:flex-start;
  background:rgba(97,246,255,.09);
  border:1px solid rgba(97,246,255,.18);
}

.from-user{
  align-self:flex-end;
  background:rgba(255,215,106,.13);
  border:1px solid rgba(255,215,106,.22);
}

.brain-form{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  gap:8px;
  padding:12px;
  border-top:1px solid rgba(255,255,255,.12);
}

.brain-form input{
  border-radius:16px;
  min-height:48px;
}

.brain-form button{
  border:1px solid rgba(255,215,106,.46);
  border-radius:16px;
  background:rgba(255,215,106,.18);
  color:var(--text);
  font-weight:900;
  padding:0 14px;
  cursor:pointer;
}

.brain-widget.is-minimized .brain-window{
  display:none;
}

.brain-widget.is-minimized .brain-fab{
  display:grid;
  place-items:center;
}

::-webkit-scrollbar{
  width:14px;
  height:14px;
}

::-webkit-scrollbar-track{
  background:rgba(255,255,255,.08);
}

::-webkit-scrollbar-thumb{
  background:linear-gradient(180deg,var(--gold),var(--cyan),var(--pink));
  border:3px solid rgba(5,3,11,.90);
  border-radius:999px;
}

@keyframes gridDrift{
  from{background-position:0 0,0 0}
  to{background-position:0 78px,78px 0}
}

@keyframes orbitPulse{
  0%,100%{transform:scale(.88);opacity:.20}
  50%{transform:scale(1.14);opacity:.64}
}

@keyframes logoFloat{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-12px)}
}

@keyframes titleShimmer{
  from{background-position:0% center}
  to{background-position:220% center}
}

@keyframes orbitTilt{
  0%,100%{transform:rotateX(0deg) rotateY(0deg)}
  50%{transform:rotateX(7deg) rotateY(-8deg)}
}

@keyframes spinOrbit{
  to{transform:rotate(360deg)}
}

@keyframes nodeFloat{
  0%,100%{margin-top:0}
  50%{margin-top:-12px}
}

@keyframes lineFlash{
  0%,100%{opacity:.15}
  50%{opacity:.55}
}

@keyframes sweep{
  0%,62%{translate:-120% 0}
  100%{translate:120% 0}
}

@keyframes consoleScan{
  to{background-position:0 28px}
}

@keyframes fabPulse{
  0%,100%{transform:scale(.92);opacity:.45}
  50%{transform:scale(1.16);opacity:1}
}

@keyframes chatRise{
  from{opacity:0;transform:translateY(16px) scale(.98)}
  to{opacity:1;transform:translateY(0) scale(1)}
}

@media(max-width:1180px){
  .command-layout,
  .brain-demo-grid{
    grid-template-columns:1fr;
  }
  .legal-orbit{
    width:min(620px,100%);
    justify-self:center;
    min-height:auto;
  }
  .route-board{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}

@media(max-width:760px){
  .legal-command-hero{
    min-height:auto;
    padding:30px 0 44px;
  }
  .spectacle-title{
    font-size:clamp(2.35rem,15vw,4.7rem);
  }
  .signal-strip,
  .route-board{
    grid-template-columns:1fr;
  }
  .legal-orbit{
    min-height:360px;
  }
  .policy-node{
    width:72px;
    font-size:.82rem;
  }
  .orbit-core{
    width:190px;
  }
  .brain-widget{
    right:10px;
    bottom:10px;
    width:calc(100vw - 20px);
  }
  .brain-messages{
    height:260px;
  }
}

@media(max-width:430px){
  .command-logo{
    width:min(230px,70vw);
  }
  .brain-form{
    grid-template-columns:1fr;
  }
  .brain-form button{
    min-height:44px;
  }
}

@media(prefers-reduced-motion:reduce){
  *,
  *:before,
  *:after{
    animation-duration:.001ms !important;
    animation-iteration-count:1 !important;
    scroll-behavior:auto !important;
  }
}

/* Magic UI text highlighter treatment */
.magic-highlighter,
.magic-highlight,
.magic-underline,
[data-highlight] {
  --highlighter-color: #87cefa;
  display: inline;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.magic-highlighter[data-highlight="highlight"],
.magic-highlight,
[data-highlight="highlight"] {
  border-radius: .18em;
  padding: 0 .12em;
  background:
    linear-gradient(104deg,
      transparent .08em,
      color-mix(in srgb, var(--highlighter-color) 68%, transparent) .08em,
      color-mix(in srgb, var(--highlighter-color) 68%, transparent) calc(100% - .08em),
      transparent calc(100% - .08em));
  text-shadow: 0 .08em .22em rgba(0, 0, 0, .16);
}

.magic-highlighter[data-highlight="underline"],
.magic-underline,
[data-highlight="underline"] {
  text-decoration-line: underline;
  text-decoration-color: var(--highlighter-color);
  text-decoration-thickness: .16em;
  text-underline-offset: .13em;
  text-decoration-skip-ink: none;
}

@supports not (color: color-mix(in srgb, white 50%, transparent)) {
  .magic-highlighter[data-highlight="highlight"],
  .magic-highlight,
  [data-highlight="highlight"] {
    background: linear-gradient(104deg, transparent .08em, var(--highlighter-color) .08em, var(--highlighter-color) calc(100% - .08em), transparent calc(100% - .08em));
  }
}

