  display:grid;
  grid-template-columns:minmax(260px,auto) minmax(0,1fr);
  align-items:center;
  gap:22px;
  padding:12px 0;
}

.brand{
  display:inline-flex;
  align-items:center;
  gap:12px;
  font-weight:950;
  letter-spacing:.04em;
  text-transform:uppercase;
  color:var(--text);
  min-width:0;
}

.brand-logo{
  width:76px;
  height:auto;
  display:block;
  object-fit:contain;
  flex:0 0 auto;
  filter:drop-shadow(0 0 18px rgba(255,215,106,.34));
}

.brand span:last-child{
