  box-shadow:0 12px 44px rgba(155,92,255,.16);
  cursor:pointer;
}

.button:hover{
  color:var(--text);
  border-color:rgba(97,246,255,.65);
}

.hero{padding:54px 0 32px}
.hero.center{text-align:center}

.hero-logo{
  display:block;
  width:min(560px,92%);
  height:auto;
  margin:0 auto 22px;
  filter:drop-shadow(0 0 36px rgba(255,215,106,.30)) drop-shadow(0 0 52px rgba(155,92,255,.23));
}

.eyebrow{
  color:var(--cyan);
  letter-spacing:.16em;
  text-transform:uppercase;
  font-size:.78rem;
  font-weight:850;
  margin-bottom:16px;
}

h1{
  font-size:clamp(2.1rem,5.7vw,5rem);
  line-height:.98;
  margin:0 0 20px;
  letter-spacing:0;
}

.page-title{font-size:clamp(2rem,4.6vw,4.1rem)}

h2{
  font-size:clamp(1.48rem,2.8vw,2.45rem);
  line-height:1.1;
  margin:0 0 16px;
  letter-spacing:0;
}

h3{font-size:1.15rem;margin:20px 0 6px}

.lede{
  max-width:900px;
  color:var(--muted);
  font-size:clamp(1.05rem,1.65vw,1.28rem);
  margin:0 0 24px;
}

.center .lede{margin-left:auto;margin-right:auto}

.glow-title{text-shadow:0 0 38px rgba(255,215,106,.24),0 0 48px rgba(155,92,255,.22)}

.grid{
  display:grid;
  grid-template-columns:repeat(12,minmax(0,1fr));
  gap:18px;
  margin:26px 0;
}

.card{
  grid-column:span 4;
  background:linear-gradient(180deg,var(--panel),rgba(255,255,255,.035));
  border:1px solid var(--line);
  border-radius:var(--radius);
  padding:24px;
  box-shadow:var(--shadow);
  position:relative;
  overflow:hidden;
  min-width:0;
}

.card.large{grid-column:span 8}
.card.full{grid-column:1/-1}

.card:before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(135deg,rgba(255,215,106,.08),transparent 35%,rgba(155,92,255,.09));
}

.card>*{position:relative}

.section{padding:34px 0}

.kicker{
  color:var(--gold);
  font-weight:850;
  text-transform:uppercase;
  letter-spacing:.12em;
  font-size:.78rem;
}

.copy p,.copy li{color:var(--muted)}
.copy strong{color:var(--text)}
.copy h2,.copy h3{color:var(--text)}

.list{
  padding-left:1.15rem;
  margin:12px 0 0;
}

.notice{
  border:1px solid rgba(255,215,106,.42);
  background:rgba(255,215,106,.08);
  color:var(--text);
  border-radius:22px;
  padding:18px;
}

.carrier-copy-section{
  border:1px solid rgba(255,215,106,.46);
  background:linear-gradient(135deg,rgba(255,215,106,.13),rgba(97,246,255,.07));
}

.carrier-copy-section p{
  color:var(--text);
  font-size:1.05rem;
}

.danger{
  border-color:rgba(255,79,216,.48);
  background:rgba(255,79,216,.075);
}

.badge-row{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  margin-top:18px;
}

.center .badge-row{justify-content:center}

.badge{
  border:1px solid var(--line);
  border-radius:999px;
  padding:8px 12px;
  color:var(--muted);
  background:rgba(255,255,255,.045);
  font-size:.88rem;
}

.legal-layout{
  display:grid;
  grid-template-columns:minmax(230px,280px) minmax(0,1fr);
  gap:24px;
  align-items:start;
}

.toc{
  position:sticky;
  top:22px;
  max-height:calc(100vh - 44px);
  overflow:auto;
  z-index:1;
}

.toc a{
  display:block;
  padding:9px 0;
  color:var(--muted);
  border-bottom:1px solid rgba(255,255,255,.07);
  font-size:.94rem;
  overflow-wrap:anywhere;
}

.toc a:hover{color:var(--gold)}

.legal-doc{
  background:linear-gradient(180deg,var(--panel),rgba(255,255,255,.035));
  border:1px solid var(--line);
  border-radius:30px;
  padding:clamp(22px,4vw,42px);
  box-shadow:var(--shadow);
  min-width:0;
  overflow-wrap:anywhere;
}

.legal-doc p,.legal-doc li{color:var(--muted)}

.legal-doc section{
  padding:22px 0;
  border-top:1px solid rgba(255,255,255,.10);
  scroll-margin-top:24px;
}

.legal-doc section:first-of-type{
  border-top:0;
  padding-top:0;
}

.meta{color:var(--muted);font-size:.95rem}

.table-wrap{
  width:100%;
  overflow-x:auto;
  border-radius:18px;
}

.table{
  width:100%;
  border-collapse:collapse;
  min-width:680px;
}

.table th,.table td{
  padding:14px;
  border-bottom:1px solid var(--line);
  text-align:left;
  vertical-align:top;
}

.table th{
  color:var(--gold);
  background:rgba(255,255,255,.055);
}

.table td{color:var(--muted)}

.form{display:grid;gap:14px}

label{
  display:grid;
  gap:8px;
  color:var(--text);
  font-weight:750;
}

input,textarea,select{
  width:100%;
  border:1px solid rgba(255,255,255,.18);
  background:rgba(0,0,0,.28);
  border-radius:16px;
  color:var(--text);
  padding:14px;
  font:inherit;
  outline:none;
}

textarea{min-height:138px;resize:vertical}

input:focus,textarea:focus,select:focus{
  border-color:var(--gold);
  box-shadow:0 0 0 4px rgba(255,215,106,.12);
}

.checkbox{
  display:grid;
  grid-template-columns:22px minmax(0,1fr);
  gap:12px;
  align-items:start;
  color:var(--muted);
  font-weight:500;
}

.checkbox input{
  width:18px;
  height:18px;
  margin-top:4px;
}

.required{color:var(--gold);font-weight:900}
.small{font-size:.92rem;color:var(--muted)}

.footer{
  margin-top:50px;
  border-top:1px solid var(--line);
  padding:30px 0 44px;
  color:var(--muted);
  background:rgba(0,0,0,.12);
}

.footer-grid{
  display:flex;
  justify-content:space-between;
  gap:22px;
  flex-wrap:wrap;
}

.footer-logo{
  width:108px;
  height:auto;
  display:block;
  margin-bottom:10px;
  filter:drop-shadow(0 0 16px rgba(255,215,106,.2));
}

@media(max-width:1120px){
  .nav{
    grid-template-columns:1fr;
    align-items:start;
  }
  .nav-links{
    justify-content:flex-start;
  }
  .legal-layout{
    grid-template-columns:1fr;
  }
  .toc{
    position:relative;
    top:auto;
    max-height:none;
  }
  .toc a{
    display:inline-flex;
    margin:4px 6px 4px 0;
    padding:8px 11px;
    border:1px solid rgba(255,255,255,.10);
    border-radius:999px;
    background:rgba(255,255,255,.045);
  }
}

@media(max-width:760px){
  .wrap,.narrow{
    width:min(100% - 26px,1180px);
  }
  .site-header{
    position:relative;
  }
  .nav{
    min-height:auto;
    gap:14px;
    padding:14px 0 16px;
  }
  .brand{
    align-items:flex-start;
    font-size:.92rem;
    line-height:1.15;
  }
  .brand-logo{
    width:58px;
  }
  .nav-links{
    width:100%;
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:8px;
  }
  .nav-links a{
    white-space:normal;
    text-align:center;
    padding:10px 9px;
  }
  .nav-links .button{
    grid-column:1/-1;
  }
  .hero{
    padding-top:34px;
  }
  .hero-logo{
    width:min(420px,96%);
  }
  .card,.card.large{
    grid-column:1/-1;
  }
  .legal-doc{
    border-radius:24px;
    padding:20px;
  }
  .toc{
    padding:18px;
  }
  .toc a{
    font-size:.9rem;
  }
  h1{
    letter-spacing:-.045em;
  }
}

@media(max-width:430px){
  .nav-links{
    grid-template-columns:1fr;
  }
  .brand-logo{
    width:52px;
  }
  .hero-logo{
    width:min(360px,98%);
  }
}


/* =========================================================
   HARD FIX: legal page overlap correction
   Root cause: global .card { grid-column: span 4; } was affecting
   .legal-layout children. Legal layout must own its children directly.
   ========================================================= */

.legal-layout{
  display:grid !important;
  grid-template-columns:minmax(240px,300px) minmax(0,1fr) !important;
  gap:28px !important;
  align-items:start !important;
  width:100% !important;
}

.legal-layout > .toc,
.legal-layout > .card.toc{
  grid-column:1 !important;
  grid-row:1 !important;
  width:100% !important;
  min-width:0 !important;
  max-width:300px !important;
  align-self:start !important;
}

.legal-layout > .legal-doc{
  grid-column:2 !important;
  grid-row:1 !important;
  width:100% !important;
  min-width:0 !important;
  max-width:100% !important;
  align-self:start !important;
}

.legal-layout .card{
  grid-column:auto !important;
}

.legal-layout .legal-doc h2{
  word-break:normal !important;
  overflow-wrap:break-word !important;
  hyphens:none !important;
}

.legal-layout .legal-doc p,
.legal-layout .legal-doc li{
  overflow-wrap:break-word !important;
}

@media(max-width:1120px){
  .legal-layout{
    grid-template-columns:1fr !important;
    gap:18px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc,
  .legal-layout > .legal-doc{
    grid-column:1 !important;
    grid-row:auto !important;
    max-width:none !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    position:relative !important;
    top:auto !important;
    max-height:none !important;
    overflow:visible !important;
  }
}

@media(max-width:760px){
  .legal-layout{
    gap:14px !important;
  }

  .legal-layout > .toc,
  .legal-layout > .card.toc{
    padding:16px !important;
  }

  .legal-layout > .legal-doc{
    padding:20px !important;
  }
}


